export interface ConnectorConfig {
  /** Notion integration token with write access to the target database. */
  notionToken: string
  /** The Notion database ID for the 'Signed' database. */
  databaseId: string
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface PipedriveWebhookPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
    webhook_id: string
    webhook_owner_id: string
    attempt: number
    host: string
  }
  data: {
    id: number
    title: string
    value: number
    owner_name: string
    close_date?: string
    status: string
    won_time?: string
    [key: string]: unknown
  }
  previous: unknown
}

export interface HandleResult {
  notionPageId: string
  dealId: number
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is PipedriveWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.meta || typeof p.meta !== 'object') {
    throw new Error('Invalid payload: missing meta object')
  }
  const meta = p.meta as Record<string, unknown>
  if (meta.action !== 'change' || meta.entity !== 'deal') {
    throw new Error('Invalid payload: not a deal change event')
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Invalid payload: missing data object')
  }
  const data = p.data as Record<string, unknown>
  if (data.status !== 'won') {
    throw new Error('Invalid payload: deal status is not won')
  }
  if (typeof data.title !== 'string' || !data.title.trim()) {
    throw new Error('Invalid payload: missing or empty title')
  }
  if (typeof data.value !== 'number' || !Number.isFinite(data.value)) {
    throw new Error('Invalid payload: missing or invalid value')
  }
  if (typeof data.owner_name !== 'string' || !data.owner_name.trim()) {
    throw new Error('Invalid payload: missing or empty owner_name')
  }
  const closeDate = data.close_date
  const wonTime = data.won_time
  if ((typeof closeDate !== 'string' || !closeDate.trim()) &&
      (typeof wonTime !== 'string' || !wonTime.trim())) {
    throw new Error('Invalid payload: missing close_date and won_time')
  }
}

function extractCloseDate(data: PipedriveWebhookPayload['data']): string {
  if (typeof data.close_date === 'string' && data.close_date.trim()) {
    return data.close_date.trim()
  }
  if (typeof data.won_time === 'string' && data.won_time.trim()) {
    return data.won_time.trim().split('T')[0]
  }
  throw new Error('Unable to determine close date')
}

function buildNotionBody(payload: PipedriveWebhookPayload, databaseId: string) {
  const data = payload.data
  const closeDate = extractCloseDate(data)
  return {
    parent: { database_id: databaseId },
    properties: {
      'Deal Title': {
        title: [{ text: { content: data.title } }]
      },
      'Deal Value': {
        number: data.value
      },
      Owner: {
        rich_text: [{ text: { content: data.owner_name } }]
      },
      'Close Date': {
        date: { start: closeDate }
      }
    }
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const typedPayload = payload as PipedriveWebhookPayload

  const body = buildNotionBody(typedPayload, config.databaseId)
  const fetchFn = getFetch(config)

  const response = await fetchFn('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.notionToken}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Notion API error: ${response.status} ${response.statusText} - POST https://api.notion.com/v1/pages - ${text}`)
  }

  const result = await response.json() as { id: string }
  return {
    notionPageId: result.id,
    dealId: typedPayload.data.id
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, PipedriveWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionToken: 'test-notion-token',
      databaseId: 'test-database-id',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(result.dealId).toBe(123)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = {
      notionToken: 'test-notion-token',
      databaseId: 'test-database-id',
      fetch
    }
  })

  it('maps all required fields correctly', async () => {
    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '456',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-1',
        webhook_owner_id: 'owner-1',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 456,
        title: 'Enterprise Deal',
        value: 50000,
        owner_name: 'Jane Smith',
        close_date: '2023-02-20',
        status: 'won',
        won_time: '2023-02-20T14:00:00Z'
      },
      previous: null
    }

    const result = await handle(payload, baseConfig)

    expect(result.dealId).toBe(456)
    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(calls).toHaveLength(1)

    const requestBody = calls[0].json as Record<string, unknown>
    expect(requestBody.parent).toEqual({ database_id: 'test-database-id' })
    expect(requestBody.properties).toEqual({
      'Deal Title': { title: [{ text: { content: 'Enterprise Deal' } }] },
      'Deal Value': { number: 50000 },
      Owner: { rich_text: [{ text: { content: 'Jane Smith' } }] },
      'Close Date': { date: { start: '2023-02-20' } }
    })
  })

  it('uses won_time when close_date is missing', async () => {
    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '789',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-2',
        webhook_owner_id: 'owner-2',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 789,
        title: 'Deal Without Close Date',
        value: 2500,
        owner_name: 'Bob Wilson',
        status: 'won',
        won_time: '2023-03-10T09:15:00Z'
      },
      previous: null
    }

    const result = await handle(payload, baseConfig)

    expect(result.dealId).toBe(789)
    const requestBody = calls[0].json as Record<string, unknown>
    expect((requestBody.properties as Record<string, unknown>)['Close Date']).toEqual({
      date: { start: '2023-03-10' }
    })
  })

  it('sends Bearer authorization header', async () => {
    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '111',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-3',
        webhook_owner_id: 'owner-3',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 111,
        title: 'Auth Test Deal',
        value: 100,
        owner_name: 'Auth User',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await handle(payload, baseConfig)

    const authHeader = calls[0].headers.get('authorization')
    expect(authHeader).toBe('Bearer test-notion-token')
  })

  it('throws on missing required field: title', async () => {
    const payload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '222',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-4',
        webhook_owner_id: 'owner-4',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 222,
        title: '',
        value: 100,
        owner_name: 'Test User',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig))
      .rejects.toThrow('Invalid payload: missing or empty title')
  })

  it('throws on missing required field: value', async () => {
    const payload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '333',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-5',
        webhook_owner_id: 'owner-5',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 333,
        title: 'Test Deal',
        value: 'not-a-number' as unknown,
        owner_name: 'Test User',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig))
      .rejects.toThrow('Invalid payload: missing or invalid value')
  })

  it('throws on missing required field: owner_name', async () => {
    const payload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '444',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-6',
        webhook_owner_id: 'owner-6',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 444,
        title: 'Test Deal',
        value: 100,
        owner_name: '',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig))
      .rejects.toThrow('Invalid payload: missing or empty owner_name')
  })

  it('throws on missing close_date and won_time', async () => {
    const payload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '555',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-7',
        webhook_owner_id: 'owner-7',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 555,
        title: 'Test Deal',
        value: 100,
        owner_name: 'Test User',
        status: 'won'
      },
      previous: null
    }

    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig))
      .rejects.toThrow('Invalid payload: missing close_date and won_time')
  })

  it('throws on non-won status', async () => {
    const payload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '666',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-8',
        webhook_owner_id: 'owner-8',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 666,
        title: 'Test Deal',
        value: 100,
        owner_name: 'Test User',
        close_date: '2023-04-01',
        status: 'open'
      },
      previous: null
    }

    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig))
      .rejects.toThrow('Invalid payload: deal status is not won')
  })

  it('throws on non-2xx response from Notion', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = {
      notionToken: 'bad-token',
      databaseId: 'test-database-id',
      fetch
    }

    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '999',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-9',
        webhook_owner_id: 'owner-9',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 999,
        title: 'Error Deal',
        value: 100,
        owner_name: 'Error User',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await expect(handle(payload, config)).rejects.toThrow('Notion API error: 401 Unauthorized - POST https://api.notion.com/v1/pages')
    expect(errorCalls).toHaveLength(1)
  })

  it('includes Notion-Version header', async () => {
    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '777',
        timestamp: '2023-01-01T00:00:00.000Z',
        version: '2.0',
        webhook_id: 'webhook-10',
        webhook_owner_id: 'owner-10',
        attempt: 1,
        host: 'company.pipedrive.com'
      },
      data: {
        id: 777,
        title: 'Version Header Test',
        value: 100,
        owner_name: 'Version User',
        close_date: '2023-04-01',
        status: 'won'
      },
      previous: null
    }

    await handle(payload, baseConfig)

    const notionVersion = calls[0].headers.get('notion-version')
    expect(notionVersion).toBe('2022-06-28')
  })
})

